#include <iostream>

using namespace std;

int main()
{
    int divisor, dividend;

    cout << "Enter dividend: ";
    cin >> dividend;

    cout << "Enter divisor: ";
    cin >> dividend;

    int quotient = dividend / divisor;
    cout << quotient << "\n";

    while (quotient > 0)
    {
        cout << dividend << "/" << divisor << " = " << quotient << " ";
        cout << "Remainder: " << dividend % divisor << "\n";

        dividend = quotient;
    }

    cout << endl;
}
